// PRIVATE original authoring corpus. Do not import into browser or public API.
// Sources establish subject areas; conditions, answers and grade anchors are
// authored proposals and have not been validated on candidates.
const grades = ['Intern', 'Junior', 'Middle', 'Senior', 'Lead'];
const rows = [];
function F(spec, group, slug, title, prompt, criteria, levels, sources, alternatives, errors, language = null) {
  const prefix = { DevOps: 'devops', QA: 'qa', Security: 'security', UXUI: 'uxui', BusinessAnalysis: 'business', ProductManagement: 'product' }[spec];
  rows.push({
    id: `open-${prefix}-${slug}`, specialization: spec, group, title, prompt,
    answerFormat: language ? 'code' : 'text', language,
    sourceIds: sources.map(id => 'ops-' + id), tags: [slug, group.toLowerCase(), language || 'scenario'],
    referenceAnswer: criteria.map(c => c[1]).join(' '),
    acceptableAlternatives: alternatives, criticalErrors: errors,
    criteria: criteria.map(([label, meets, strong], i) => ({
      id: 'criterion-' + (i + 1), label,
      missing: 'Не рассматривает требование: ' + label + '.',
      partial: 'Называет ' + label + ', но не обосновывает необходимое действие: ' + meets,
      meets, strong,
    })),
    levels: Object.fromEntries(grades.map((grade, i) => [grade, { task: levels[i][0], expected: levels[i][1] }])),
    personalization: { allowed: ['domain', 'entityNames'], invariants: [
      'Сохранить числа, порядок событий, доступные сведения, права и ограничения ресурсов.',
      'Сохранить задачу уровня, обязательные критерии, альтернативы и критические ошибки.',
      'Самоописание опыта меняет контекст, но не добавляет баллы и не подтверждает авторство.',
    ] },
  });
}

F('DevOps','A','dns-cache','Кэш после смены DNS','Адрес api.example изменён с узла A на B. Новый DNS-ответ виден на ноутбуке, но сервис ещё ходит на A. TTL был 300 секунд. Объясните проверку без отключения DNS.',[
 ['Место кэша','Сопоставить authoritative ответ, системный резолвер и кэш процесса.','Проверить разные процессы и время получения записей.'],
 ['Переход','Учесть прежний TTL и сохранять работоспособность A до окончания перехода.','Проверить соединения, которые переживают TTL.'],
 ['Проверка','Записать фактический адрес назначения и повторить запрос после обновления кэша.','Отличить DNS от пула постоянных соединений.']
],[['Покажите, что проверить на одном клиенте.','Сравнивает полученный адрес и адрес соединения.'],['Добавьте второй процесс на том же узле.','Разделяет системный и процессный кэш.'],['Клиенты используют три резолвера.','Строит проверяемую матрицу резолверов и времени TTL.'],['A нельзя выключить без потери запросов.','Планирует перекрытие и наблюдение за оставшимися соединениями.'],['Подобные смены нужны десяти сервисам.','Предлагает стандарт перехода с измеримым окончанием и исключениями.']],['sre-troubleshooting'],['Сброс конкретного процессного кэша после проверки его роли.'],['Считать успешный dig доказательством обновления всех клиентов.']);

F('DevOps','A','tls-name','TLS и имя сервиса','Клиент открывает https://files.example, сертификат действителен для media.example. TCP устанавливается. Разберите причину и безопасное исправление.',[
 ['Проверка имени','Проверить соответствие запрошенного имени SAN сертификата.','Отличить ошибку имени от срока и цепочки доверия.'],
 ['SNI и маршрут','Сопоставить SNI, виртуальный хост и сертификат на точке завершения TLS.','Проверить каждый адрес балансировщика.'],
 ['Исправление','Выдать подходящий сертификат либо исправить ошибочное имя клиента.','Проверить обновление без отключения проверки TLS.']
],[['Назовите несовпадение в данных.','Указывает files.example против media.example.'],['Проверьте одну точку TLS.','Предлагает проверку имени, цепочки и SNI.'],['Ошибка только на одном из двух узлов.','Локализует различие сертификатов и конфигурации.'],['Клиенты закрепляют доверенный корень.','Планирует совместимость цепочки и безопасный откат.'],['Нужен контроль сотни имён.','Определяет автоматическую проверку имени, срока и маршрута.']],['sre-troubleshooting'],['Сертификат с обоими разрешёнными именами.'],['Отключить проверку сертификата.']);

F('DevOps','A','ports','Порты и границы сети','Процесс слушает 127.0.0.1:9000 внутри контейнера. Балансировщик обращается к адресу контейнера на 9000 и получает отказ. Опишите цепочку проверки.',[
 ['Интерфейс','Определить, что loopback контейнера не принимает запросы на его внешний интерфейс.','Подтвердить адрес слушателя и пространство имён.'],
 ['Маршрут','Проверить маршрут, порт и правила сети отдельно от состояния процесса.','Сравнить запрос из контейнера и из соседнего узла.'],
 ['Безопасный доступ','Выбрать нужный интерфейс и ограничить разрешённые источники.','Проверить недоступность для запрещённого источника.']
],[['Поясните два адреса.','Различает loopback и сетевой адрес контейнера.'],['Предложите локальный фикс.','Меняет привязку с сохранением сетевых ограничений.'],['В цепочке также proxy и firewall.','Проверяет каждый переход, не открывая все порты.'],['Сервис переносится между подсетями.','Сохраняет границу доступа при смене маршрута.'],['Нужен стандарт публикации сервисов.','Определяет проверку слушателя, маршрута и минимально разрешённых потоков.']],['k8s-network'],['Локальный proxy, принимающий разрешённые внешние запросы.'],['Открыть все порты всем источникам.']);

F('DevOps','A','fd-budget','Бюджет файловых дескрипторов','Лимит процесса 1024 дескриптора, 200 заняты служебными файлами. Каждое соединение требует два. Напишите функцию расчёта максимума соединений с резервом 100.',[
 ['Расчёт','Вычесть служебные 200 и резерв 100; взять целую часть 724/2: 362.','Проверить нечётный остаток.'],
 ['Границы','Для отрицательного остатка вернуть ноль или явную ошибку конфигурации.','Проверить нулевую стоимость и отрицательные параметры.'],
 ['Эксплуатация','Считать лимит процесса, а не только общесистемный лимит.','Сопоставить расчёт с фактическими открытыми дескрипторами.']
],[['Вычислите результат для данных чисел.','Получает 362 без округления вверх.'],['Реализуйте функцию для переданных чисел.','Проверяет входы и целое деление.'],['Служебное потребление меняется от 200 до 350.','Использует верхнюю границу и объясняет резерв.'],['Нужно выбирать между повышением лимита и ограничением приёма.','Обосновывает обе меры и контроль утечек.'],['Функция используется несколькими сервисами.','Задаёт единый контракт расчёта и проверку запасов при изменении нагрузки.']],['sre-overload'],['Явная ошибка при недостаточном бюджете вместо нуля.'],['Игнорировать два дескриптора на соединение.'],'python');

F('DevOps','A','log-sockets','Подсчёт сетевых ошибок','Даны записи (host, outcome) со значениями ok, timeout, refused. Напишите функцию, возвращающую по хостам число timeout и refused; неизвестный outcome нужно отдельно учитывать.',[
 ['Группировка','Группировать по host и типу ошибки, не смешивая timeout с refused.','Проверить два хоста с одинаковым типом ошибки.'],
 ['Полнота','Не считать ok ошибкой; неизвестные значения помещать в отдельный счётчик.','Проверить пустой вход и новый outcome.'],
 ['Диагностика','Интерпретировать timeout и refused как разные наблюдения, а не доказанные причины.','Предложить проверку доступности порта для каждого класса.']
],[['Посчитайте ошибки для [(a,ok),(a,timeout),(b,refused),(a,unknown)].','Для a: timeout=1, refused=0, unknown=1; для b: refused=1.'],['Реализуйте функцию и проверьте пустой список и два хоста.','Возвращает отдельные счётчики и пустой результат.'],['Логи поступают потоково; опишите обновление счётчиков без хранения всех записей.','Использует ограниченное состояние на наблюдаемый хост.'],['Кардинальность host не ограничена; предложите лимит памяти и отчёт о превышении.','Предлагает ограничение памяти без тихой потери неизвестных значений.'],['Результат станет общей панелью сети; задайте контракт исходов и ограничения выводов.','Определяет таксономию исходов и ограничения интерпретации.']],['sre-troubleshooting'],['SQL GROUP BY по host и outcome при заданной схеме.'],['Объявить каждый timeout доказанным падением сервера.'],'python');

F('DevOps','A','clock-order','Часы и порядок событий','Узел A пишет 12:00:05 «отправлено», B пишет 12:00:03 «получено». Максимальное расхождение часов не известно. Объясните, что можно заключить и какие данные нужны.',[
 ['Неопределённость','Не выводить отрицательное время передачи только из двух wall-clock меток.','Обозначить пределы выводов без оценки clock skew.'],
 ['Измерение','Для локальных длительностей использовать монотонные часы.','Разделить длительность процесса и межузловой порядок.'],
 ['Связь событий','Связать отправку и получение идентификатором и проверить синхронизацию часов.','Добавить последовательность событий и оценку неопределённости.']
],[['Объясните видимое противоречие.','Допускает расхождение часов.'],['Предложите журналирование одного запроса.','Использует correlation ID и локальные длительности.'],['Три узла имеют разный skew.','Не строит точный порядок только по времени.'],['Расследуется нарушение таймаута.','Определяет достоверные измерения и границы оценки.'],['Нужен стандарт времени для нескольких систем.','Разделяет timestamp, монотонную длительность и причинную связь в контракте.']],['sre-troubleshooting'],['Причинные последовательности при корректно заданном протоколе.'],['Считать разницу меток точной сетевой задержкой.']);

F('DevOps','A','disk-inodes','Свободные гигабайты без новых файлов','На файловой системе свободно 40 ГБ, но создание маленького файла завершается ENOSPC. Каталог содержит миллионы мелких файлов. Составьте безопасную диагностику.',[
 ['Ресурс','Проверить свободные inode отдельно от свободных блоков.','Уточнить квоты пользователя и фактический mount.'],
 ['Локализация','Найти источник количества файлов и его политику хранения.','Сопоставить скорость создания и удаления.'],
 ['Очистка','Удалять только подтверждённые ненужные данные с проверкой владельца и срока.','Проверить остановку роста после исправления источника.']
],[['Назовите дополнительный ресурс.','Указывает inode.'],['Дайте последовательность безопасных проверок.','Проверяет inode, mount и квоты до очистки.'],['Файлы создают два процесса.','Разделяет вклад процессов и устраняет рост.'],['Каталог содержит незавершённые задания.','Сохраняет активные файлы и проектирует хранение.'],['Такие каталоги есть во многих сервисах.','Определяет квоты, метрики inode и политику уборки.']],['sre-troubleshooting'],['Вынос подтверждённого архива на отдельную файловую систему.'],['Удалить весь каталог без проверки назначения файлов.']);

F('DevOps','A','memory-rss','Память и завершение процесса','Контейнер ограничен 512 МБ. После обработки крупного ответа процесс завершён; график CPU нормальный. Лог приложения не содержит исключения. Разберите следующий шаг.',[
 ['Причина завершения','Проверить статус завершения и признаки OOM, не объявляя его доказанным заранее.','Сопоставить событие с RSS и лимитом.'],
 ['Потребление','Разделить память приложения, буферы и суммарный лимит контейнера.','Измерить пик при обработке конкретного размера ответа.'],
 ['Ограничение','Предложить потоковую обработку или лимит размера с проверкой поведения.','Сравнить с увеличением памяти и риском повторного роста.']
],[['Скажите, почему CPU недостаточно.','Память является отдельным ресурсом.'],['Подготовьте проверку одной загрузки.','Сопоставляет peak memory и событие завершения.'],['Одновременно обрабатываются четыре ответа.','Учитывает суммарный пик и конкуренцию.'],['Один большой клиент влияет на всех.','Ограничивает объём и параллелизм с наблюдением результата.'],['Нужны ресурсные контракты сервисов.','Задаёт лимиты входа, измерение пиков и политику исключений.']],['sre-overload'],['Дисковое промежуточное хранение с заданными лимитами.'],['Увеличивать память без измерения и ограничения входа.']);

F('DevOps','A','dns-timeout-budget','Бюджет сетевого запроса','Общий deadline 800 мс: DNS занял 150, соединение 200, TLS 100. На ответ осталось время. Объясните настройку этапов и повторов.',[
 ['Остаток','После трёх этапов остаётся 350 мс общего deadline.','Учесть потраченное время повторов.'],
 ['Таймауты','Не назначать каждому этапу новый полный бюджет 800 мс.','Разделить connect, handshake и чтение.'],
 ['Повторы','Повторять только допустимую операцию и только внутри остатка бюджета.','Учесть идемпотентность и отмену работы после deadline.']
],[['Рассчитайте остаток.','Получает 350 мс.'],['Опишите таймауты одного запроса.','Передаёт остаток между этапами.'],['Добавьте один безопасный повтор.','Проверяет оставшийся бюджет и идемпотентность.'],['Запрос проходит три сервиса.','Не обновляет deadline на каждом переходе.'],['Нужен общий сетевой контракт.','Определяет перенос deadline, политику повторов и измерение этапов.']],['sre-overload'],['Более строгие этапные таймауты внутри общего deadline.'],['Обновить полный deadline при каждом повторе.']);

F('DevOps','A','packet-size','Малые запросы проходят, большие зависают','Небольшие HTTPS-запросы проходят через VPN, большие ответы зависают. Без VPN проблема не наблюдается. CPU и доступность сервиса нормальные. Предложите проверяемые гипотезы.',[
 ['Гипотеза','Рассмотреть MTU и потерю информации о допустимом размере пакета наряду с другими причинами.','Проверить порог размера и направление трафика.'],
 ['Эксперимент','Сравнить захват трафика и контролируемые размеры через оба маршрута.','Отличить сетевую потерю от timeout приложения.'],
 ['Изменение','Исправлять согласование размера или туннель после подтверждения причины.','Проверить отсутствие скрытого обхода сетевой защиты.']
],[['Назовите зависимость от размера.','Предлагает проверить размер и маршрут.'],['Опишите контролируемый тест.','Сравнивает размеры через VPN и без него.'],['Зависание только в одном направлении.','Проверяет асимметричный путь и ICMP.'],['VPN используется несколькими приложениями.','Сравнивает изменение MTU/MSS и побочные эффекты.'],['Нужен сетевой стандарт туннелей.','Определяет тесты размера пакета и наблюдаемость маршрутов.']],['sre-troubleshooting'],['Подтверждённая настройка MSS вместо изменения MTU конечных узлов.'],['Отключить VPN как постоянное решение без анализа границ доступа.']);

F('DevOps','B','state-lock','Конкурирующие изменения инфраструктуры','Два CI задания читают одно инфраструктурное состояние и одновременно применяют разные изменения. Одно завершилось, другое потеряло lock. Составьте безопасный порядок продолжения.',[
 ['Единственный писатель','Сериализовать изменения одного состояния.','Проверить конкуренцию разных очередей.'],['Свежесть плана','После первого изменения пересчитать второй план.','Проверить расхождение ревизий.'],['Снятие lock','Снимать блокировку только после подтверждения отсутствия активного владельца.','Записать основание ручного вмешательства.']
],[['Разберите два писателя.','Обнаруживает конфликт общего состояния.'],['Предложите порядок двух запусков.','Применяет второй свежий план последовательно.'],['Один runner недоступен.','Проверяет владельца lock до освобождения.'],['Есть несколько pipeline на одном backend.','Обеспечивает общий механизм сериализации.'],['Определите правила изменения десяти окружений.','Разделяет области состояния и единый порядок восстановления.']],['terraform-lock'],['Очередь изменений с одним исполнителем.'],['Снимать чужую активную блокировку.']);
F('DevOps','B','drift','Изменение ресурса вне кода','Вручную увеличили число реплик с 3 до 5. В коде осталось 3, следующий план возвращает 3. Сервис выдерживает нагрузку только при 5. Объясните согласование состояния.',[
 ['Различие','Различить желаемую конфигурацию и наблюдаемое состояние.','Проверить автора и причину ручного изменения.'],['Безопасный план','До apply проверить влияние возврата к трём репликам.','Проверить ёмкость при потере одной реплики.'],['Согласование','Зафиксировать обоснованное изменение в источнике конфигурации.','Добавить обнаружение drift.']
],[['Назовите различие.','Показывает 3 против 5.'],['Предложите локальное согласование.','Проверяет нагрузку и обновляет конфигурацию.'],['Ручные изменения затронули два ресурса.','Рассматривает полный план, а не одну строку.'],['Часть ручных изменений аварийная.','Разделяет временное исключение и постоянную конфигурацию.'],['Нужна политика drift для окружений.','Определяет сигнал, срок исключения и проверяемое согласование.']],['terraform-lock'],['Контролируемый возврат к 3 после снижения нагрузки.'],['Применить план вслепую.']);
F('DevOps','B','secret-rotation','Ротация ключа без простоя','API принимает ключ K1; клиенты обновляются постепенно. Новый K2 готов, но одновременно обновить клиентов нельзя. Спроектируйте ротацию.',[
 ['Перекрытие','Временно принимать K1 и K2, затем отозвать K1.','Проверить срок и границы перекрытия.'],['Проверка перехода','Измерять использование версии ключа без записи самого секрета.','Проверить оставшихся клиентов.'],['Отзыв','Обеспечить отзыв старого ключа и проверку отказа K1.','Предусмотреть аварийную ротацию.']
],[['Опишите роль двух ключей.','Различает выпуск и отзыв.'],['Дайте порядок обновления клиентов.','Использует безопасное перекрытие.'],['Один клиент не обновляется.','Определяет срок и обработку исключения.'],['K1 мог быть раскрыт.','Сокращает перекрытие и ограничивает риск.'],['Ротация нужна всем интеграциям.','Определяет владельцев, учёт версий и проверяемый отзыв.']],['k8s-secrets'],['Параллельные учётные записи с отдельным отзывом.'],['Писать ключи в журнал.']);
F('DevOps','B','least-network','Разрешённые сетевые потоки','Frontend должен обращаться к API на 8080, API к БД на 5432. Иных потоков нет; DNS нужен обоим. Опишите политику сети.',[
 ['Минимальные потоки','Разрешить frontend→API и API→БД с заданными портами.','Проверить обратные и посторонние обращения.'],['DNS','Сохранить доступ к согласованному DNS.','Проверить фактический адрес и порт резолвера.'],['Проверка отказов','Проверить как разрешённые, так и запрещённые соединения.','Учесть поддержку политики сетевым движком.']
],[['Нарисуйте два основных потока.','Правильно связывает сервисы и порты.'],['Добавьте DNS и запрещённый поток.','Не открывает весь исходящий трафик.'],['Сервисы находятся в разных namespace.','Учитывает селекторы и границы namespace.'],['Меняются адреса БД.','Не подменяет устойчивую идентичность произвольным IP.'],['Нужен сетевой шаблон платформы.','Определяет явные исключения и проверку enforcement.']],['k8s-network'],['Эквивалентные firewall правила с проверенными источниками.'],['Считать описание политики доказательством её исполнения.']);
F('DevOps','B','resource-limits','Запросы и лимиты ресурсов','Три процесса имеют request 200 МБ и limit 800 МБ каждый; узел располагает 2 ГБ для них. Оцените риск размещения и проверки.',[
 ['Резервация','Сумма requests 600 МБ не описывает максимальное потребление.','Разделить резерв и ограничение.'],['Пик','Суммарный возможный пик 2400 МБ превышает 2 ГБ.','Проверить одновременную нагрузку.'],['Меры','Ограничить параллелизм или изменить размещение по измеренным пикам.','Учитывать запас узла.']
],[['Сравните две суммы.','Получает 600 и 2400 МБ.'],['Предложите безопасное размещение.','Учитывает реальный пик и запас.'],['Пики коррелируют по расписанию.','Не предполагает независимые всплески.'],['Узел может потерять соседний узел.','Проверяет перераспределение при отказе.'],['Нужна политика ресурсов.','Определяет измерение пиков и предел overcommit.']],['sre-overload'],['Перенос процессов на дополнительные узлы.'],['Считать requests гарантией отсутствия OOM.']);
F('DevOps','B','config-precedence','Конфликт настроек','Для TIMEOUT заданы файл=5, переменная окружения=8, аргумент CLI=2 секунды. Контракт: CLI выше env, env выше файла. Напишите функцию выбора с проверкой положительного значения.',[
 ['Приоритет','Выбирать CLI, затем env, затем файл; для примера получить 2.','Проверить отсутствие каждого источника.'],['Валидация','Отличать отсутствующее значение от нуля и ошибки формата.','Проверить отрицательное и дробное значение.'],['Прозрачность','Сообщать выбранный источник без раскрытия секретных настроек.','Проверить диагностическое сообщение.']
],[['Вычислите итог.','Получает 2 секунды.'],['Реализуйте выбор трёх значений.','Соблюдает приоритет и отсутствие.'],['CLI содержит строку bad.','Не маскирует ошибку более слабым источником.'],['Настройки меняются при запуске.','Фиксирует применённый снимок и проверяет формат.'],['Функция станет общей библиотекой.','Определяет единицы, ошибки и совместимость контракта.']],['sre-troubleshooting'],['Явный отказ запуска на невалидной настройке.'],['Использовать truthy проверку, теряя ноль.'],'python');
F('DevOps','B','manifest-check','Проверка конфигураций сервисов','Дан список словарей name, replicas, memoryMb. Требуются уникальные имена, replicas≥1 и memoryMb≥64. Напишите валидатор, возвращающий все ошибки с индексом записи.',[
 ['Правила','Проверить уникальность и обе нижние границы.','Проверить точные границы 1 и 64.'],['Типы','Отклонять отсутствующие поля и неверные числовые типы.','Не принимать boolean как число.'],['Отчёт','Вернуть все ошибки с индексами без изменения входа.','Проверить несколько ошибок одной записи.']
],[['Проверьте записи [{name:a,replicas:1,memoryMb:64},{name:b,replicas:0,memoryMb:63}].','Первая корректна; у второй две ошибки границ.'],['Напишите валидатор списка и покажите результат для пустого входа.','Возвращает полный перечень ошибок.'],['Проверьте [{name:a,replicas:1,memoryMb:64},{name:a,replicas:1}].','Разделяет ошибку уникальности и отсутствие memoryMb.'],['Формат расширяется новыми полями; задайте правило совместимости валидатора.','Определяет совместимость и строгую проверку значений.'],['Проверка используется перед всеми rollout; предложите версионирование правил.','Задаёт единый контракт ошибок и версий правил.']],['k8s-deploy'],['Строгая схема плюс отдельная проверка уникальности.'],['Проверять только первую ошибку вопреки контракту.'],'python');
F('DevOps','B','volume-state','Данные после замены контейнера','Приложение сохраняет задания во внутренний каталог контейнера. После пересоздания они исчезают. Внешний диск доступен, но два экземпляра могут писать одновременно. Предложите хранение.',[
 ['Жизненный цикл','Отделить временную файловую систему от устойчивого хранения.','Проверить mount и права доступа.'],['Конкуренция','Задать безопасное владение данными при двух писателях.','Проверить совместимость режима доступа диска.'],['Восстановление','Проверить рестарт с сохранением заданий и восстановление копии.','Отличить устойчивый диск от резервной копии.']
],[['Объясните потерю.','Указывает временный каталог контейнера.'],['Опишите один устойчивый экземпляр.','Подключает проверенное внешнее хранение.'],['Добавьте второй писатель.','Разрешает конкуренцию явно.'],['Нужен перенос между узлами.','Проверяет целостность и восстановление.'],['Выберите стандарт хранения заданий.','Сравнивает файловое хранение с БД по отказам и стоимости.']],['k8s-deploy'],['Хранение заданий в транзакционной БД.'],['Считать внешний диск резервной копией.']);
F('DevOps','B','image-identity','Тег образа изменился','Два окружения запускают tag=stable, но содержат разные версии. Тег был перезаписан между запуском окружений. Предложите воспроизводимость.',[
 ['Идентичность','Различить изменяемый тег и digest содержимого.','Сопоставить фактические digest.'],['Фиксация','Закреплять один проверенный digest для продвижения.','Не пересобирать отдельно для production.'],['Происхождение','Сохранить связь исходников, сборки и артефакта.','Проверить журнал продвижения.']
],[['Назовите причину расхождения.','Тег может ссылаться на другой образ.'],['Зафиксируйте одну версию.','Использует digest и связь со сборкой.'],['Есть три окружения.','Продвигает один артефакт последовательно.'],['Registry зеркалируется.','Проверяет целостность и происхождение копии.'],['Нужен стандарт артефактов.','Определяет неизменность, хранение и разрешённый откат.']],['actions-security'],['Неизменяемые уникальные теги с подтверждённым контролем registry.'],['Считать stable неизменяемым идентификатором.']);
F('DevOps','B','environment-isolation','Тестовая среда обращается к production','После клонирования конфигурации staging пишет в production БД. Секреты и DNS одинаковы. Планируйте исправление и проверку изоляции.',[
 ['Граница','Разделить адреса, учётные записи и полномочия окружений.','Проверить сетевой запрет staging→production.'],['Остановка ущерба','Остановить ошибочные записи и сохранить сведения об изменениях.','Проверить уже затронутые данные.'],['Проверка','Добавить проверку целевого окружения до запуска.','Проверить отказ при неверной конфигурации.']
],[['Назовите опасный поток.','Staging пишет в production.'],['Предложите локальное разделение.','Использует отдельные адрес и credentials.'],['Конфигурация наследуется автоматически.','Проверяет наследование и fail-closed запуск.'],['Есть общие read-only сервисы.','Описывает явные разрешённые исключения.'],['Нужна модель окружений.','Определяет идентичность, границы и проверяемую изоляцию.']],['k8s-network','k8s-secrets'],['Отдельные аккаунты инфраструктуры.'],['Удалить следы ошибочных записей.']);

F('DevOps','C','readiness','Готовность и живость','После запуска сервис жив, но прогревает кэш 40 секунд. Балансировщик сразу направляет запросы, получающие 503. Разделите проверки и доставку.',[
 ['Готовность','Не включать экземпляр в трафик до готовности обслуживать.','Проверить прогрев на холодном старте.'],['Живость','Не перезапускать исправно прогревающийся процесс проверкой готовности.','Проверить петлю рестартов.'],['Выпуск','Сохранять достаточную старую ёмкость при прогреве новых экземпляров.','Проверить отказ одного нового экземпляра.']
],[['Назовите два состояния.','Различает запущен и готов.'],['Предложите две проверки.','Разделяет readiness и liveness.'],['Выпускаются четыре реплики.','Учитывает прогрев и доступную ёмкость.'],['Прогрев зависит от внешнего сервиса.','Ограничивает ожидание и предотвращает каскадные рестарты.'],['Проверки нужны платформе.','Определяет контракты готовности и безопасного rollout.']],['k8s-deploy'],['Явная задержка включения при проверяемом условии готовности.'],['Перезапускать сервис каждые десять секунд прогрева.']);
F('DevOps','C','canary','Сигнал канареечного выпуска','Канарейка получает 5% трафика. Её ошибки 4%, остальные экземпляры 0.2%; общий график показывает 0.39%. Решите, что проверить перед расширением.',[
 ['Сегмент','Сравнить канарейку отдельно от общего среднего.','Проверить одинаковые типы запросов.'],['Остановка','При нарушении заранее заданного критерия остановить расширение.','Сохранить наблюдения для диагностики.'],['Достоверность','Учитывать число запросов и окно измерения.','Проверить локализацию по маршрутам.']
],[['Сравните две доли.','Замечает деградацию канарейки.'],['Предложите критерий остановки.','Не скрывает 4% общим графиком.'],['Канарейке достались сложные запросы.','Проверяет состав трафика.'],['Есть редкие критические операции.','Использует отдельные защитные метрики.'],['Нужна политика canary.','Задаёт стратификацию, объём наблюдений и откат.']],['k8s-deploy','sre-monitoring'],['Остановка выпуска с возвратом проверенного артефакта.'],['Расширять rollout только по общему среднему.']);
F('DevOps','C','expand-contract','Миграция при смешанных версиях','Версия v1 читает колонку name, v2 читает display_name. Во время выпуска обе работают. Переименование колонки одним шагом ломает v1. Предложите последовательность.',[
 ['Совместимость','Добавить новое представление без немедленного удаления старого.','Проверить чтение обеих версий.'],['Перенос','Перенести данные и обеспечить согласование новых записей.','Проверить пропуски и повторный backfill.'],['Удаление','Удалять старую схему только после прекращения использования v1.','Проверить условия отката.']
],[['Укажите несовместимость.','V1 теряет name.'],['Предложите этап добавления.','Сохраняет совместимость старой версии.'],['Данные меняются во время backfill.','Обеспечивает согласование записей.'],['Откат v2 возможен сутки.','Сохраняет старое чтение и данные в окне отката.'],['Нужен стандарт миграций.','Определяет expand, перенос и контролируемый contract.']],['k8s-deploy'],['Версионированное совместимое API хранения.'],['Удалить старую колонку до обновления клиентов.']);
F('DevOps','C','artifact-promotion','Сборка после тестирования','В staging протестирован артефакт D1. Перед production pipeline пересобирает код и выпускает D2 без повторных тестов. Проверьте процесс.',[
 ['Связь проверки','Результат тестов D1 не автоматически относится к D2.','Проверить digest обоих артефактов.'],['Продвижение','Продвигать проверенный артефакт либо повторить проверку нового.','Отделить настройки окружения от сборки.'],['Аудит','Хранить связь версии, тестового отчёта и выпуска.','Проверить восстановимость цепочки.']
],[['Назовите разрыв.','Тестировали D1, выпускают D2.'],['Исправьте один pipeline.','Продвигает тот же артефакт.'],['Есть зависимости сборки из сети.','Фиксирует происхождение и неизменность входов.'],['Для окружений различается конфигурация.','Разделяет артефакт и runtime настройки.'],['Определите стандарт promotion.','Задаёт проверяемое доказательство допуска артефакта.']],['actions-security'],['Повторное тестирование D2 с отдельным допуском.'],['Приписывать D2 результаты тестов D1.']);
F('DevOps','C','feature-flag','Флаг и необратимое действие','Новая функция включается флагом. Она отправляет реальные письма; выключение флага не отменяет уже отправленные. Разберите план выпуска и возврата.',[
 ['Обратимость','Отделить выключение функции от отмены её побочных действий.','Перечислить необратимые эффекты.'],['Ограничение','Начать с контролируемой аудитории и ограничить объём отправок.','Проверить повторные задания.'],['Контроль','Фиксировать версию поведения и идентичность отправки.','Определить действия после ошибочной рассылки.']
],[['Назовите необратимое действие.','Письмо нельзя отозвать флагом.'],['Предложите безопасный пилот.','Ограничивает аудиторию и объём.'],['Задания остаются в очереди после выключения.','Обрабатывает старые задания явно.'],['Несколько сервисов используют флаг.','Обеспечивает согласованное выключение эффектов.'],['Нужна политика функциональных выпусков.','Разделяет reversible rollout и компенсацию последствий.']],['sre-postmortem'],['Dry-run на синтетических адресах до реальной отправки.'],['Обещать, что выключение флага отменяет письма.']);
F('DevOps','C','pipeline-dag','Зависимости pipeline','Даны jobs build→unit, build→scan, unit+scan→deploy. Напишите проверку графа: каждый dependency существует, цикл запрещён, deploy не запускается до всех успешных предшественников.',[
 ['Граф','Проверить существование узлов и обнаружить цикл.','Проверить самоссылку.'],['Порядок','Получить топологический порядок или явную ошибку.','Проверить независимые ветки.'],['Допуск','Требовать успех всех зависимостей deploy.','Отличить completed от successful.']
],[['Нарисуйте порядок заданий.','Deploy зависит от unit и scan.'],['Реализуйте проверку небольшого графа.','Выявляет отсутствующую зависимость и цикл.'],['Одна ветка завершается ошибкой.','Блокирует deploy при failed scan.'],['Допустимы условные jobs.','Определяет семантику skipped без обхода контроля.'],['Графы создают разные команды.','Задаёт версионированный контракт допуска и ошибок графа.']],['actions-security'],['DFS с цветами или алгоритм Кана.'],['Считать завершившуюся ошибкой проверку успешной.'],'python');
F('DevOps','C','digest-check','Проверка допуска артефакта','Запись допуска содержит digest и expiresAt. Запрос выпуска содержит digest и время serverNow. Напишите проверку совпадения digest и срока; отсутствие полей отклоняется.',[
 ['Идентичность','Сравнить полный digest, не тег или префикс.','Проверить похожие значения.'],['Срок','При now≥expiresAt отклонить допуск.','Проверить точную границу срока.'],['Доверие','Допуск должен быть получен из доверенного хранилища.','Не принимать его из произвольного клиента.']
],[['Проверьте пару digest вручную.','Замечает несовпадение.'],['Напишите функцию и граничные примеры.','Проверяет поля и срок.'],['Клиент прислал собственный допуск.','Не доверяет клиентскому доказательству.'],['Часы runner ошибаются.','Использует серверное время и проверенный формат.'],['Допуск применяется в нескольких CI.','Определяет общий источник доверия и отзыв допуска.']],['actions-security'],['Подписанное доказательство с проверкой ключа и срока.'],['Принимать совпадение только первых символов digest.'],'python');
F('DevOps','C','pr-secrets','Секреты в сборке внешнего PR','Внешний PR изменяет сборочный скрипт. Pipeline запускает этот скрипт с production token. Предложите разделение проверок.',[
 ['Недоверенный код','Код внешнего PR считать недоверенным.','Проверить изменяемые действия и зависимости.'],['Полномочия','Не предоставлять production token недоверенной сборке.','Использовать минимальные отдельные права.'],['Доверенный выпуск','Разделить проверки PR и выпуск одобренного артефакта.','Проверить отсутствие обхода через повторный запуск.']
],[['Назовите риск.','Скрипт может прочитать token.'],['Разделите два pipeline.','PR проверяется без production secret.'],['PR меняет используемую action.','Учитывает всю цепочку исполняемого кода.'],['Артефакт PR передаётся в доверенный job.','Проверяет происхождение и не исполняет непроверенный результат.'],['Определите стандарт CI доверия.','Фиксирует границы прав и разрешённые переходы артефактов.']],['actions-security'],['Изолированная сборка с отдельными краткоживущими правами.'],['Выдать production token любому внешнему PR.']);
F('DevOps','C','rollback-data','Откат после записи нового формата','V2 записывает данные в формате, который v1 не читает. Выпуск ухудшил latency. Откат бинарника возможен, но обратного преобразования данных нет. Опишите решение.',[
 ['Ограничение отката','Не считать возврат v1 безопасным для уже изменённых данных.','Проверить масштабы новых записей.'],['Снижение ущерба','Ограничить новое поведение и выбрать совместимую версию исправления.','Разделить rollback и roll-forward.'],['Проверка данных','Проверить чтение всех форматов и план восстановления.','Сохранить исходные данные перед преобразованием.']
],[['Назовите препятствие откату.','V1 не читает новый формат.'],['Предложите локальное снижение ущерба.','Не выполняет слепой бинарный откат.'],['Данные распределены по двум хранилищам.','Проверяет согласованность и возможность roll-forward.'],['Преобразование частично необратимо.','Определяет доказательства восстановления и окно потери.'],['Нужна политика совместимости выпусков.','Задаёт проверки форматов и критерии допустимого отката.']],['sre-postmortem'],['Совместимая промежуточная версия, читающая оба формата.'],['Откатить код без проверки совместимости данных.']);
F('DevOps','C','deployment-capacity','Ёмкость при rolling update','Четыре реплики обслуживают по 100 rps; вход 350 rps. Во время rollout две старые отключаются до готовности новых. Обоснуйте безопасный план.',[
 ['Расчёт','Две доступные реплики дают только 200 rps против 350.','Учесть деградацию производительности.'],['Порядок','Не удалять старую ёмкость до готовности необходимой новой.','Проверить ограничения ресурсов на добавление.'],['Защита','Остановить rollout при нехватке готовой ёмкости.','Проверить отказ одной реплики.']
],[['Посчитайте доступную ёмкость.','Получает 200 rps.'],['Предложите последовательность замены.','Сохраняет минимум четыре готовые реплики.'],['Можно временно добавить одну реплику.','Использует surge и проверяет readiness.'],['Нагрузка может достигнуть 450 rps.','Проверяет запас и остановку выпуска.'],['Определите стандарт rollout по ёмкости.','Связывает параметры выпуска с измеренной производительностью и отказами.']],['k8s-deploy','sre-overload'],['Временное ограничение нагрузки в согласованном окне.'],['Считать желаемые реплики уже готовыми.']);

F('DevOps','D','sli-counter','Подсчёт успешных запросов','Дан список (eligible, status, durationMs). Хороший запрос: eligible=true, status=ok, durationMs≤300. Напишите good/total; при total=0 верните отсутствие значения.',[
 ['Знаменатель','Считать только eligible запросы.','Проверить исключённые ошибки.'],['Успех','Проверить статус и границу 300 мс одновременно.','Проверить быстрый ошибочный ответ.'],['Пустое окно','При нуле допустимых запросов вернуть unknown, не 100%.','Проверить пустой список.']
],[['Посчитайте [(true,ok,300),(true,error,10),(false,ok,20)].','Good=1, total=2, доля=0.5; третья запись исключена.'],['Напишите агрегатор и проверьте пустой список и точную границу 300 мс.','Проверяет границы и отсутствие значения.'],['Два узла сообщили good,total=(1,2) и (9,9); вычислите общую долю.','Суммирует счётчики: 10/11, не средние доли.'],['Доля eligible меняется после выпуска; определите проверку сопоставимости.','Контролирует изменение определения SLI.'],['Нужен общий контракт SLI; задайте версии определения и обработку unknown.','Версионирует eligibility, good и unknown.']],['sre-slo'],['Возвращать пару good,total для последующей агрегации.'],['Превратить окно без запросов в 100% успеха.'],'python');
F('DevOps','D','incident-intervals','Длительность инцидентов','Даны интервалы недоступности [start,end) в минутах: [2,7), [5,9), [12,14). Напишите функцию общей недоступности без двойного счёта.',[
 ['Объединение','Отсортировать и объединить пересечения; итог 9 минут.','Проверить вложенные интервалы.'],['Границы','Использовать полузакрытые интервалы и проверить end≥start.','Проверить касающиеся интервалы.'],['Окно','Обрезать интервалы границами окна измерения.','Проверить инцидент, пересекающий обе границы окна.']
],[['Посчитайте заданные интервалы.','Получает 7+2=9 минут.'],['Реализуйте объединение.','Не считает пересечение дважды.'],['Инциденты пересекают суточное окно.','Обрезает интервалы корректно.'],['Часть интервалов ещё открыта.','Определяет верхнюю границу и неизвестность.'],['Метрика объединяет несколько источников.','Задаёт семантику времени, dedup и незавершённых событий.']],['sre-slo'],['Sweep-line по начальным и конечным событиям.'],['Просто суммировать длительности пересекающихся инцидентов.'],'python');
F('DevOps','D','burn-budget','Расход бюджета ошибок','SLO=99.9% за 30 дней, наблюдались 21.6 минуты недоступности. Рассчитайте бюджет и долю расхода; предложение выпускать дальше нужно обосновать.',[
 ['Бюджет','30 дней=43200 минут; бюджет 43.2 минуты.','Проверить единицы и период.'],['Расход','Расход 21.6/43.2=50%.','Отличить остаток бюджета от текущего error rate.'],['Решение','Связать выпуск с заранее согласованной политикой риска.','Учесть скорость расхода и оставшееся время.']
],[['Вычислите допустимые минуты.','Получает 43.2 минуты.'],['Определите расход.','Получает 50%.'],['Осталась половина периода.','Сравнивает расход с оставшимся временем.'],['Инцидент расходует бюджет очень быстро.','Использует краткие окна и ограничивает риск.'],['Нужна политика бюджета выпуска.','Определяет остановку, исключения и восстановление допуска.']],['sre-slo'],['Request-based бюджет при явно ином определении SLO.'],['Считать 99.9% обещанием отсутствия сбоев.']);
F('DevOps','D','p95-vs-mean','Средняя задержка скрывает хвост','Средняя latency упала с 100 до 80 мс; p95 вырос с 250 до 900 мс. Ошибки не изменились. Предложите проверку пользовательского ухудшения.',[
 ['Распределение','Не считать снижение среднего улучшением для всех запросов.','Проверить p99 и число наблюдений.'],['Сегменты','Разделить маршруты, регионы и размеры ответа.','Проверить изменение состава трафика.'],['Действие','Сравнить хвост с целевым SLI и локализовать медленные операции.','Сопоставить трассировки и версию.']
],[['Укажите противоречие метрик.','Замечает рост p95.'],['Предложите проверку одного маршрута.','Измеряет распределение.'],['Изменился состав клиентов.','Проверяет сегменты и сравнимые группы.'],['Общие зависимости обслуживают разные маршруты.','Локализует вклад через трассировки.'],['Определите стандарт latency.','Задаёт перцентили, сегменты и измеримый критерий деградации.']],['sre-monitoring'],['Доля запросов быстрее согласованного порога.'],['Оценить качество только по среднему.']);
F('DevOps','D','alert-noise','Сотни сигналов без влияния','CPU alert срабатывает каждые две минуты, но пользовательские запросы успешны. Один реальный отказ потерялся среди уведомлений. Пересмотрите правила.',[
 ['Симптом','Отделить пользовательский ущерб от диагностического CPU.','Проверить связь с latency и ошибками.'],['Маршрут','Разделить срочный page и несрочное исследование.','Описать действие для каждого уведомления.'],['Качество','Измерить шум, пропуски и время реакции.','Проверить правила на прошлых инцидентах.']
],[['Назовите проблему уведомлений.','CPU сам по себе не доказывает отказ.'],['Предложите два маршрута сигналов.','Page связан с действием и ущербом.'],['Есть отказ без роста CPU.','Проверяет пользовательский SLI.'],['Шум поступает из нескольких зависимостей.','Группирует сигналы без сокрытия независимых отказов.'],['Нужен стандарт alerting.','Задаёт критерии полезности и проверку пропусков.']],['sre-monitoring'],['CPU сигнал как ticket для прогноза ёмкости.'],['Отключить все уведомления.']);
F('DevOps','D','restore-drill','Копия существует, восстановление нет','Резервные задания всегда зелёные. При восстановлении обнаружили отсутствующий ключ шифрования. RPO=1 час, RTO=2 часа. Спроектируйте проверку.',[
 ['Восстановимость','Проверить копию вместе с ключами и зависимостями.','Провести восстановление в изолированной среде.'],['Цели','Измерить фактическую потерю данных и время восстановления.','Проверить RPO и RTO отдельно.'],['Целостность','Проверить содержимое и возможность работы после восстановления.','Сравнить контрольные записи.']
],[['Укажите недостающую зависимость.','Нужен ключ расшифровки.'],['Составьте локальную тренировку.','Проверяет чтение копии.'],['Восстановление включает два хранилища.','Проверяет согласованную точку восстановления.'],['Основной регион недоступен.','Проверяет независимость копий и ключей.'],['Нужна программа восстановления.','Задаёт регулярные испытания и доказательства RPO/RTO.']],['sre-postmortem'],['Раздельно защищённое резервирование ключей.'],['Считать успешное копирование доказательством восстановления.']);
F('DevOps','D','retry-storm','Повторы при перегрузке','При ошибке каждый из 1000 клиентов повторяет запрос немедленно три раза. Сервер уже перегружен. Предложите ограничение и проверку.',[
 ['Усиление','Рассчитать рост запросов и обнаружить положительную обратную связь.','Учесть вложенные retries.'],['Ограничение','Использовать bounded retries, backoff с jitter и общий deadline.','Проверить идемпотентность операции.'],['Восстановление','Снизить приём и наблюдать восстановление очередей.','Проверить нагрузку при снятии ограничений.']
],[['Назовите эффект повторов.','Они усиливают перегрузку.'],['Предложите политику клиента.','Ограничивает повторы и интервал.'],['Два слоя повторяют независимо.','Задаёт общий бюджет попыток.'],['Ошибки затрагивают оплату.','Разделяет безопасный повтор и неопределённый результат.'],['Нужен общий retry стандарт.','Определяет deadline, jitter, бюджеты и измерение усиления.']],['sre-overload'],['Circuit breaker при корректно заданных условиях открытия.'],['Повторять бесконечно без задержки.']);
F('DevOps','D','load-shedding','Очередь перед отказом','Вход 1200 задач/мин, обработка 1000/мин; очередь 4000, срок задачи 5 минут. Оцените устойчивость и допустимый приём.',[
 ['Рост','Очередь растёт на 200 задач в минуту.','Проверить временной горизонт.'],['Срок','Текущая очередь соответствует примерно 4 минутам обработки без нового входа.','Учесть дальнейший рост и deadline задач.'],['Приём','Ограничить приём и отклонять или переносить задачи явно.','Не скрывать потерянные задания.']
],[['Рассчитайте рост.','Получает 200 в минуту.'],['Предложите ограничение приёма.','Удерживает нагрузку ниже устойчивой ёмкости.'],['Задачи имеют разные сроки.','Выбирает осмысленную политику очереди.'],['Увеличение работников перегружает БД.','Проверяет узкое место зависимости.'],['Определите контракт перегрузки.','Задаёт лимиты, приоритеты и явный результат отказа.']],['sre-overload'],['Дополнительная ёмкость после проверки зависимостей.'],['Молча удалять задачи из очереди.']);
F('DevOps','D','postmortem-actions','Разбор повторяющегося сбоя','Трижды ошибка конфигурации выключала сервис; каждый раз записали «быть внимательнее». Предложите полезный разбор и проверяемые действия.',[
 ['Причинная цепочка','Описать технические и процессные условия, не искать виноватого.','Отделить наблюдение от гипотезы.'],['Меры','Предложить проверку конфигурации и ограничение воздействия изменения.','Задать проверяемое окончание работы.'],['Эффект','Проверить меры повторным сценарием ошибки.','Измерить уменьшение обнаружения и восстановления.']
],[['Назовите недостаток текущего действия.','Внимательность не является проверяемым контролем.'],['Предложите одну техническую меру.','Автоматически проверяет опасную настройку.'],['Ошибка затрагивает два сервиса.','Рассматривает причинную цепочку и blast radius.'],['Все проверки проходят, но ошибка возможна.','Дополняет контроль безопасным rollout и восстановлением.'],['Нужна программа предотвращения повторов.','Приоритизирует проверяемые меры по риску и следит за их эффектом.']],['sre-postmortem'],['Безопасное значение по умолчанию плюс ограничение изменения.'],['Заменить разбор поиском виноватого.']);
F('DevOps','D','capacity-forecast','Прогноз ёмкости','Диск 1 ТБ, занято 700 ГБ, рост 10 ГБ/день. Подготовка нового диска занимает 20 дней; резерв должен быть 100 ГБ. Оцените момент действия.',[
 ['Горизонт','До резерва 200 ГБ, то есть 20 дней.','Проверить единицы и отсутствие ускорения роста.'],['Срок подготовки','Начинать действие сейчас, поскольку срок подготовки равен горизонту.','Добавить запас неопределённости.'],['Контроль','Мониторить фактический рост и варианты временного ограничения.','Проверить отклонение прогноза.']
],[['Вычислите оставшиеся дни.','Получает 20 дней до резерва.'],['Назовите момент заказа.','Заказывает сейчас с учётом lead time.'],['Рост может достигнуть 15 ГБ/день.','Проверяет неблагоприятный сценарий.'],['Сокращение данных требует проверки хранения.','Сравнивает расширение и безопасное уменьшение объёма.'],['Нужен стандарт capacity planning.','Задаёт прогноз, lead time, резерв и действия при отклонениях.']],['sre-monitoring'],['Подтверждённое снижение роста с сохранением нужных данных.'],['Ждать полного заполнения диска.']);

F('QA','A','expiry-contract','Точная граница срока','Token истекает в 12:00:00 UTC; контракт разрешает доступ только при now<expiresAt. Функция valid(now,expiresAt) возвращает boolean. Напишите проверки требований.',[
 ['Граница','Проверить момент до, ровно на и после срока; равенство запрещено.','Использовать минимальный поддерживаемый шаг времени.'],['Часы','Задавать время явно без ожидания реальных часов.','Проверить неверный формат и единицы.'],['Трассировка','Связать каждую проверку с правилом срока.','Отделить проверку авторизации от проверки времени.']
],[['Назовите три момента.','Покрывает точное равенство.'],['Напишите детерминированные проверки.','Ожидает true,false,false.'],['Клиент и сервер имеют разные часы.','Проверяет серверный источник времени.'],['Срок зависит от обновления token.','Уточняет атомарность продления и проверки.'],['Нужно единое правило срока.','Определяет контракт времени и согласованные проверки сервисов.']],['istqb','yandex-qa'],['Табличные параметризованные тесты.'],['Разрешить запрос ровно в expiresAt.'],'python');
F('QA','A','money-rounding','Требование округления денег','Заказ: две позиции по 10.05, скидка 10%. Правило: считать в десятичных единицах и округлять итог half-up до копеек один раз. Функция total(items,discount) доступна. Напишите проверки.',[
 ['Эталон','Итог 20.10×0.9=18.09, без округления каждой позиции.','Добавить пример, где порядок округления меняет итог.'],['Представление','Не использовать неточный float как денежный эталон.','Проверить decimal или целочисленные копейки.'],['Границы','Проверить нулевую скидку, полный дисконт и запрещённые значения.','Отдельно проверить точную половину копейки.']
],[['Рассчитайте один эталон.','Получает 18.09.'],['Напишите проверки функции.','Использует точное представление.'],['Добавьте возврат части заказа.','Уточняет правило распределения скидки.'],['Два сервиса округляют по-разному.','Локализует расхождение контракта.'],['Нужен стандарт денежного тестирования.','Закрепляет единицы, округление и межсервисные эталоны.']],['istqb'],['Decimal либо корректная рациональная арифметика.'],['Считать float независимым точным эталоном.'],'python');
